#include <iostream>

void mostrar_pendientes(int cantidad) {
    if (cantidad == 0) {
        return;
    }
    std::cout << "Pending: " << cantidad << "\n";
}

int main() {
    mostrar_pendientes(0);
    mostrar_pendientes(3);
    std::cout << "End";
    return 0;
}

#include <iostream>

bool cabe(int cantidad, int capacidad) {
    return (cantidad >= 0) && (cantidad <= capacidad);
}

int main() {
    if (cabe(5, 4)) {
        std::cout << "Fits";
    } else {
        std::cout << "Does not fit";
    }
    return 0;
}

